// Build URL from variables, update for each dashboard
const url = `${control_url}/rti/collector_service/rest1/metrics:update_subscription_state`;
// Build resourceSelector from variables, update for each dashboard
const resourceSelector = `${http_resource_selector}//data_writers/*`;

/*
 * This function will create the request header
 *
 * Note: Should not need to be modified for each dashboard
 */
function createHeaders(authentication) {

  const authArray = authentication.split(":")
  const headers = new Headers()

  headers.append('Content-Type', 'application/json')
  if (authArray.length === 2) {
    console.log("Adding authorization header")
    headers.append(authArray[0], authArray[1])
  }

  return headers
}

/*
 * This function will build the body for the HTTP request
 *
 * Note: Should not need to be modified for each dashboard
 */
function buildRequestBody() {
  // the json body for the POST request
  let body = [];
  // local variable to collect the subscribed metric settings
  let subscribeMetrics = [];
  // local variable to collect the unsubscribed metric settings
  let unsubscribeMetrics = [];
  // local init object to update the "initial" values with
  // the current values if the POST is successful
  let init = {};

  // gather up the modified metric settings
  elements.forEach((element) => {

    // update the local init structure with all of the current values
    init[element.id] = element.value;

    // capture all elements that are enabled
    if (element.value === `Enable`) {
      subscribeMetrics.push(element.id)
    }

    // capture all elements that are disabled
    if (element.value === `Disable`) {
      unsubscribeMetrics.push(element.id)
    }
  });

  // create the metricSettingEntry object
  let metricSettingEntry = {};
  metricSettingEntry['resource_selector'] = resourceSelector;
  metricSettingEntry['subscribe_metrics_selectors'] = subscribeMetrics;
  metricSettingEntry['unsubscribe_metrics_selectors'] = unsubscribeMetrics;
  // add the metricSettingEntry object to the body
  body.push(metricSettingEntry);

  return body
}

/*
 * This function will handle errors caught in the fetch request
 *
 * Note: Should not need to be modified for each dashboard
 */
function handleError(error) {
  if (error.name === 'TypeError') {
    // could get here because ERR_CONNECTION_REFUSED 
    // could get here because ERR_NAME_NOT_RESOLVED 
    console.log('fetch() failed to access the server.');
    notifyError(['Initialize', 'Server not found or request refused.']);
  } else if (error.name === 'AbortError') {
    console.log('The fetch()() operation timed out');
    notifyError(['Initialize', 'Request timed out.']);
  } else {
    console.log('fetch() failed');
    console.log(error);
    notifyError(['Initialize', 'Unknown failure.']);
  }
}

/*
 * This function will send an HTTP query to update the data
 *
 * Note: Should not need to be modified for each dashboard
 */
async function updateData() {

  const timeout = 3000;
  const controller = new AbortController();
  const id = setTimeout(() => controller.abort(), timeout);
  const reqHeaders = createHeaders(`${authentication_header}`);

  // local object to update the "initial" values with
  // the current values if the POST is successful
  let currentValues = {};
  elements.forEach((element) => {
    // update the local currentValues structure with all of the current values
    currentValues[element.id] = element.value;
  });

  // create the request body
  let body = buildRequestBody();

  fetch(url, {
    method: 'POST',
    headers: reqHeaders,
    signal: controller.signal,
    body: JSON.stringify(body),
  })
    .then(async response => {
      if (response.ok) {
        console.log("Successful Update!!");
        // update the "initial" values with the successful updates
        setInitial(currentValues);
        notifySuccess(['Update', 'Values updated successfully. Dashboard will refresh automatically.']);
        // reload dashboard to update everything
        setTimeout(() => {
          //delay the reload a bit to give the service time to catch up
          locationService.reload();
        }, 3000);
      } else {
        console.log("Unsuccessful Update!!");
        responseJson = await response.json();
        notifyError([responseJson['code'], responseJson['message']]);
        // the request failed call the initialRequest() code to get current values
        initialRequest();
      }
    })
    .catch(error => {
      handleError(error);
      // the request failed call the initialRequest() code to get current values
      initialRequest();
    });
}

updateData();

